-- Objects of the schema-tools specs, in their own schema. Deterministic, then ANALYZE.
SELECT setseed(0.42);

CREATE SCHEMA schema_tools;

CREATE TABLE schema_tools.customers (
    id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email      text NOT NULL,
    name       text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT customers_email_key UNIQUE (email),
    CONSTRAINT customers_email_check CHECK (email LIKE '%@%')
);
COMMENT ON TABLE schema_tools.customers IS 'registered customers';
COMMENT ON COLUMN schema_tools.customers.email IS 'login email';
INSERT INTO schema_tools.customers (email, name, created_at)
SELECT 'user' || i || '@example.com', 'customer ' || i, timestamptz '2025-01-01 00:00:00+00' + (i || ' minutes')::interval
FROM generate_series(1, 1000) AS i;

CREATE TABLE schema_tools.orders (
    id          bigint PRIMARY KEY,
    customer_id integer NOT NULL REFERENCES schema_tools.customers ON DELETE CASCADE,
    status      text NOT NULL DEFAULT 'new',
    total       numeric(10,2),
    parent_id   bigint REFERENCES schema_tools.orders (id)
);
COMMENT ON TABLE schema_tools.orders IS 'customer orders';
CREATE INDEX orders_customer_id_idx ON schema_tools.orders (customer_id);
INSERT INTO schema_tools.orders (id, customer_id, status, total)
SELECT i, 1 + (i * 7) % 1000, (ARRAY['new', 'paid', 'shipped'])[1 + (i % 3)], round((random() * 500)::numeric, 2)
FROM generate_series(1, 3000) AS i;

CREATE FUNCTION schema_tools.orders_touch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.status := lower(NEW.status);
    RETURN NEW;
END
$$;
CREATE TRIGGER orders_touch BEFORE UPDATE ON schema_tools.orders
    FOR EACH ROW EXECUTE FUNCTION schema_tools.orders_touch();

DO $$
BEGIN
    EXECUTE 'CREATE TABLE schema_tools.wide (' ||
        (SELECT string_agg(format('wide_column_%s int', lpad(i::text, 2, '0')), ', ' ORDER BY i) FROM generate_series(1, 60) AS i) || ')';
    EXECUTE 'INSERT INTO schema_tools.wide SELECT ' ||
        (SELECT string_agg('g', ', ') FROM generate_series(1, 60)) || ' FROM generate_series(1, 10) AS g';
END
$$;

CREATE TABLE schema_tools.events_p (
    id         integer NOT NULL,
    created_at timestamptz NOT NULL,
    kind       text
) PARTITION BY RANGE (created_at);
CREATE TABLE schema_tools.events_p_2025 PARTITION OF schema_tools.events_p
    FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
CREATE TABLE schema_tools.events_p_2026 PARTITION OF schema_tools.events_p
    FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
INSERT INTO schema_tools.events_p
SELECT i, timestamptz '2025-01-01 00:00:00+00' + ((i % 300) || ' days')::interval + (i || ' seconds')::interval, 'k' || (i % 4)
FROM generate_series(1, 500) AS i;
INSERT INTO schema_tools.events_p
SELECT i, timestamptz '2026-01-01 00:00:00+00' + ((i % 500) || ' hours')::interval + (i || ' seconds')::interval, 'k' || (i % 4)
FROM generate_series(501, 1000) AS i;

CREATE VIEW schema_tools.active_customers AS
SELECT id, email FROM schema_tools.customers WHERE name IS NOT NULL;

CREATE SEQUENCE schema_tools.invoice_seq AS bigint START 1000 INCREMENT 10;
SELECT setval('schema_tools.invoice_seq', 1490);

ANALYZE schema_tools.customers, schema_tools.orders, schema_tools.wide, schema_tools.events_p,
        schema_tools.events_p_2025, schema_tools.events_p_2026;

GRANT USAGE ON SCHEMA schema_tools TO pgdba_ro;
GRANT SELECT ON ALL TABLES IN SCHEMA schema_tools TO pgdba_ro;
GRANT SELECT ON ALL SEQUENCES IN SCHEMA schema_tools TO pgdba_ro;
